// SPDX-License-Identifier: MPL-2.0
//! Time zones (`docs/THINK-2026-11-02-time-zones.md`): UTC ↔ local time for a
//! zone from the IANA tz database, DST included. Pure: no allocation, no
//! syscall, `no_std`. Host KATs: `tools/tz-logic-tests` (mounted by
//! `#[path]`), every expected value worked out by hand.
//!
//! The table (`tz_table.rs`) is generated by `cargo xtask tzdata` from a
//! tz release and checked in. Each zone carries its **final POSIX TZ rule**
//! (the footer `zic` writes into its TZif file), parsed at generation time,
//! so nothing here parses strings. That rule is exact for every time after
//! the release's last explicit transition in the zone, which covers the
//! present; an earlier date converts with the final rule (THINK §2.4).
//!
//! Offsets are seconds **east** of UTC (New York in winter is -18000).

/// One DST transition: day `weekday` (0 = Sunday) of week `week` (1..=4, or
/// 5 = the last) of `month` (1..=12), at `time` seconds after local midnight
/// in the offset in force before the transition. `time` may be negative or
/// past 24 h (RFC 8536 §3.3.1): `America/Nuuk` changes at -1:00.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Transition {
    pub month: u8,
    pub week: u8,
    pub weekday: u8,
    pub time: i32,
}

/// The daylight half of a rule.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Dst {
    pub offset: i32,
    pub abbr: &'static str,
    /// Into DST (local standard time).
    pub start: Transition,
    /// Out of DST (local daylight time).
    pub end: Transition,
}

/// A zone's rule: standard time, and DST if the zone observes it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rule {
    pub std_offset: i32,
    pub std_abbr: &'static str,
    pub dst: Option<Dst>,
}

/// A zone in the table. Its index is its stable id ([`ZoneId`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Zone {
    pub name: &'static str,
    pub rule: Rule,
}

/// A stable zone id: the index into [`ZONES`]. Ids are append-only across
/// tz releases; 0 is `UTC`.
pub type ZoneId = u16;

/// The offset in force at an instant.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Offset {
    pub seconds: i32,
    pub abbr: &'static str,
    /// The rule's DST part is in force. Not "summer time": a zone with
    /// negative DST has it in winter (Europe/Dublin: GMT in winter is DST,
    /// IST in summer is standard). Show `abbr`; don't infer a season.
    pub is_dst: bool,
}

/// A local wall time read back as UTC.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LocalResult {
    /// Exactly one instant shows this wall time.
    Single(i64),
    /// Two instants do (the repeated hour when clocks go back): the earlier
    /// and the later.
    Ambiguous(i64, i64),
    /// None does (the hour skipped when clocks go forward). The two readings:
    /// with the offset in force before the gap, and with the one after it.
    Gap {
        offset_before: i64,
        offset_after: i64,
    },
}

mod table {
    use super::{Dst, Rule, Transition, Zone, ZoneId};
    include!("tz_table.rs");
}

#[allow(unused_imports)] // the host test crate mounts this file without using every name
pub use table::{LINKS, TZDATA_COMMIT, TZDATA_VERSION, ZONES};

/// The id of `UTC`.
pub const UTC: ZoneId = 0;

/// The zone with this id.
pub fn zone(id: ZoneId) -> Option<&'static Zone> {
    ZONES.get(id as usize)
}

/// A zone by IANA name or alias, ignoring ASCII case (`america/new_york`,
/// `US/Eastern`).
pub fn zone_by_name(name: &str) -> Option<ZoneId> {
    if let Some(i) = ZONES.iter().position(|z| z.name.eq_ignore_ascii_case(name)) {
        return Some(i as ZoneId);
    }
    LINKS
        .iter()
        .find(|(alias, _)| alias.eq_ignore_ascii_case(name))
        .map(|&(_, id)| id)
}

/// Days from 1970-01-01 to `y-m-d` (proleptic Gregorian; Hinnant's
/// days-from-civil).
pub const fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m as i64 + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

/// The civil year containing day `days` since 1970-01-01.
const fn year_of(days: i64) -> i64 {
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    yoe + era * 400 + if m <= 2 { 1 } else { 0 }
}

const fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

const fn month_days(y: i64, m: u8) -> u32 {
    match m {
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    }
}

/// Seconds since 1970 (local, as if UTC) of a transition's day in year `y`,
/// plus its time.
fn transition_local(t: Transition, y: i64) -> i64 {
    let first = days_from_civil(y, t.month as u32, 1);
    // 1970-01-01 was a Thursday (4).
    let first_wd = (first + 4).rem_euclid(7);
    let mut day = 1 + (t.weekday as i64 - first_wd).rem_euclid(7);
    day += 7 * (t.week as i64 - 1);
    let last = month_days(y, t.month) as i64;
    while day > last {
        day -= 7;
    }
    (first + day - 1) * 86400 + t.time as i64
}

/// The instants the rule arithmetic evaluates: ±2^40 s (about ±34,800
/// years). An instant outside is evaluated at the nearest bound (the final
/// rule repeats every year, so the offset is that year's), and results are
/// saturated, so every function here is defined, and never overflows, for
/// any `i64` (Dexter, #59).
pub const INSTANT_MAX: i64 = 1 << 40;
pub const INSTANT_MIN: i64 = -INSTANT_MAX;

const fn clamp(t: i64) -> i64 {
    if t < INSTANT_MIN {
        INSTANT_MIN
    } else if t > INSTANT_MAX {
        INSTANT_MAX
    } else {
        t
    }
}

/// The offset in force at `utc` (seconds since 1970, UTC).
pub fn offset_at(rule: &Rule, utc: i64) -> Offset {
    let utc = clamp(utc);
    let standard = Offset {
        seconds: rule.std_offset,
        abbr: rule.std_abbr,
        is_dst: false,
    };
    let Some(dst) = rule.dst else {
        return standard;
    };
    let year = year_of((utc + rule.std_offset as i64).div_euclid(86400));
    // Each transition is checked in the year of the instant and its
    // neighbours, so a transition time past midnight of 31 December (or
    // before 1 January) still lands in the right year.
    let mut in_dst = false;
    let mut latest = i64::MIN;
    for y in [year - 1, year, year + 1] {
        let start = transition_local(dst.start, y) - rule.std_offset as i64;
        let end = transition_local(dst.end, y) - dst.offset as i64;
        if start <= utc && start > latest {
            latest = start;
            in_dst = true;
        }
        if end <= utc && end > latest {
            latest = end;
            in_dst = false;
        }
    }
    if in_dst {
        Offset {
            seconds: dst.offset,
            abbr: dst.abbr,
            is_dst: true,
        }
    } else {
        standard
    }
}

/// `utc` as local seconds (local wall time counted as if UTC) and the offset.
pub fn utc_to_local(utc: i64, id: ZoneId) -> (i64, Offset) {
    let rule = zone(id).map_or(ZONES[0].rule, |z| z.rule);
    let offset = offset_at(&rule, utc);
    (utc.saturating_add(offset.seconds as i64), offset)
}

/// A local wall time (seconds since 1970, counted as if UTC) as UTC.
pub fn local_to_utc(local: i64, id: ZoneId) -> LocalResult {
    let rule = zone(id).map_or(ZONES[0].rule, |z| z.rule);
    let Some(dst) = rule.dst else {
        return LocalResult::Single(local.saturating_sub(rule.std_offset as i64));
    };
    let as_std = local.saturating_sub(rule.std_offset as i64);
    let as_dst = local.saturating_sub(dst.offset as i64);
    let std_ok = offset_at(&rule, as_std).seconds == rule.std_offset;
    let dst_ok = offset_at(&rule, as_dst).seconds == dst.offset;
    match (std_ok, dst_ok) {
        (true, true) => LocalResult::Ambiguous(as_std.min(as_dst), as_std.max(as_dst)),
        (true, false) => LocalResult::Single(as_std),
        (false, true) => LocalResult::Single(as_dst),
        (false, false) => {
            // In the gap: the offset before it is the one in force a day
            // earlier (longer than any gap).
            let before = offset_at(&rule, as_std.min(as_dst).saturating_sub(86400)).seconds as i64;
            let after = if before == rule.std_offset as i64 {
                dst.offset as i64
            } else {
                rule.std_offset as i64
            };
            LocalResult::Gap {
                offset_before: local.saturating_sub(before),
                offset_after: local.saturating_sub(after),
            }
        }
    }
}

/// The true UTC instant of an RTC reading `wall` (seconds since 1970, the
/// wall time counted as if UTC), by the session's settings
/// (THINK-2026-11-02-time-zones §2.1, §2.3):
///
/// * an RTC that holds UTC (`rtc_local` false): the reading is UTC;
/// * an RTC that holds local time in `zone`: the local reading as UTC; an
///   ambiguous one (a boot in the repeated autumn hour) takes the earlier
///   instant, as Windows does; one in the spring gap (which a correct RTC
///   can't hold) takes the offset in force after the gap;
/// * an RTC that holds local time with no zone set ([`UTC`], id 0): unknown.
pub fn rtc_reading_utc(wall: i64, zone: ZoneId, rtc_local: bool) -> Option<i64> {
    if !rtc_local {
        return Some(wall);
    }
    if zone == UTC {
        return None;
    }
    Some(match local_to_utc(wall, zone) {
        LocalResult::Single(u) => u,
        LocalResult::Ambiguous(earlier, _) => earlier,
        LocalResult::Gap { offset_after, .. } => offset_after,
    })
}

/// What `CLOCK_REALTIME` holds, from `SYS_CLOCK_REALTIME_STATUS`
/// (THINK-2026-11-02-time-zones §2.1).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Basis {
    /// The kernel has no `rtc-offset` (the status call fails): realtime is
    /// the computer's clock as read, and Home shows it as it always did, with
    /// no zone and no marker (the kill-switch's behaviour).
    Legacy,
    /// Not confirmed yet: the computer's clock as read, possibly local time.
    Rtc,
    /// Confirmed UTC. From here on only the display applies the zone: a
    /// later zone or RTC-mode change never re-interprets the instant.
    Utc,
}

impl Basis {
    /// The basis for a status call's result.
    pub fn of(status: Result<bool, i64>) -> Self {
        match status {
            Ok(true) => Self::Utc,
            Ok(false) => Self::Rtc,
            Err(_) => Self::Legacy,
        }
    }
}

/// The label after the time Home shows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shown {
    /// [`Basis::Legacy`]: none.
    Plain,
    /// [`Basis::Rtc`]: "zone not set" (the reading isn't known to be UTC).
    NotSet,
    /// [`Basis::Utc`]: the zone's abbreviation ("UTC" for no zone).
    Zone(&'static str),
}

/// The wall time (seconds, counted as if UTC) Home shows for `realtime` and
/// its label. Only [`Basis::Utc`] applies the zone; the other two show the
/// reading as it is.
pub fn shown(realtime: i64, basis: Basis, zone: ZoneId) -> (i64, Shown) {
    match basis {
        Basis::Legacy => (realtime, Shown::Plain),
        Basis::Rtc => (realtime, Shown::NotSet),
        Basis::Utc => {
            let (local, offset) = utc_to_local(realtime, zone);
            (
                local,
                Shown::Zone(if zone == UTC { "UTC" } else { offset.abbr }),
            )
        }
    }
}

/// The offset to confirm (`SYS_CLOCK_CONFIRM_REALTIME`) for an RTC reading
/// `wall`: the reading less its true UTC instant, or `None` when that is
/// unknown ([`rtc_reading_utc`]).
pub fn confirm_offset(wall: i64, zone: ZoneId, rtc_local: bool) -> Option<i64> {
    rtc_reading_utc(wall, zone, rtc_local).and_then(|utc| wall.checked_sub(utc))
}

/// After a confirm of `confirmed` for the RTC reading `wall` (the reading
/// the confirm was computed from), whether the settings now in force would
/// have read that same reading differently: then only a restart applies
/// them (the confirm is write-once), and Home says so.
///
/// It re-reads the confirm's own reading, never the clock now: a reading
/// taken later can fall in another season, and comparing its offset with
/// the confirmed one asked for a restart after every DST change (Janus,
/// #60). The same zone always reads the same reading the same way, and so
/// does any zone with the same rules.
pub fn needs_restart(wall: i64, confirmed: i64, zone: ZoneId, rtc_local: bool) -> bool {
    confirm_offset(wall, zone, rtc_local) != Some(confirmed)
}

/// A Home verb about the clock (THINK-2026-11-02-time-zones §2.5). The WM
/// answers these itself; they never reach Arthur.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ClockVerb<'a> {
    /// `timezone`: show the zone, its offset and the RTC mode.
    Show,
    /// `timezone <name>`: the name as typed (see [`find_zone`]).
    Zone(&'a [u8]),
    /// `rtc local` (true) / `rtc utc` (false).
    Rtc(bool),
}

fn trim(b: &[u8]) -> &[u8] {
    let start = b.iter().position(|&c| c != b' ').unwrap_or(b.len());
    let end = b.iter().rposition(|&c| c != b' ').map_or(start, |i| i + 1);
    &b[start..end]
}

/// The clock verb an intent-field line is, if any (ASCII case ignored,
/// surrounding spaces ignored). `rtc` with anything but `local`/`utc` is not
/// a verb: it goes to Arthur like any other line.
pub fn parse_verb(line: &[u8]) -> Option<ClockVerb<'_>> {
    let line = trim(line);
    let (word, rest) = match line.iter().position(|&c| c == b' ') {
        Some(i) => (&line[..i], trim(&line[i..])),
        None => (line, &line[line.len()..]),
    };
    if word.eq_ignore_ascii_case(b"timezone") {
        return Some(if rest.is_empty() {
            ClockVerb::Show
        } else {
            ClockVerb::Zone(rest)
        });
    }
    if word.eq_ignore_ascii_case(b"rtc") {
        if rest.eq_ignore_ascii_case(b"local") {
            return Some(ClockVerb::Rtc(true));
        }
        if rest.eq_ignore_ascii_case(b"utc") {
            return Some(ClockVerb::Rtc(false));
        }
    }
    None
}

/// `a` equals `b` ignoring ASCII case, with a space in `a` matching `_`.
fn same_name(a: &[u8], b: &[u8]) -> bool {
    a.len() == b.len()
        && a.iter()
            .zip(b)
            .all(|(&x, &y)| x.eq_ignore_ascii_case(&y) || (x == b' ' && y == b'_'))
}

fn contains_name(hay: &[u8], needle: &[u8]) -> bool {
    !needle.is_empty() && hay.windows(needle.len()).any(|w| same_name(needle, w))
}

/// A zone for what the user typed: an IANA name or alias in any case
/// (`america/new_york`, `US/Eastern`), spaces for underscores
/// (`America/New York`), or a city alone when exactly one zone ends in it
/// (`new york`, `sydney`). `utc` is zone 0. Otherwise `Err` with up to three
/// zones whose names contain it, for the card's suggestions.
pub fn find_zone(typed: &[u8]) -> Result<ZoneId, [Option<ZoneId>; 3]> {
    let typed = trim(typed);
    if let Some(i) = ZONES
        .iter()
        .position(|z| same_name(typed, z.name.as_bytes()))
    {
        return Ok(i as ZoneId);
    }
    if let Some(&(_, id)) = LINKS
        .iter()
        .find(|(alias, _)| same_name(typed, alias.as_bytes()))
    {
        return Ok(id);
    }
    let city = |z: &Zone| z.name.rsplit('/').next().unwrap_or(z.name);
    let mut found = None;
    let mut count = 0;
    for (i, z) in ZONES.iter().enumerate() {
        if same_name(typed, city(z).as_bytes()) {
            found = Some(i as ZoneId);
            count += 1;
        }
    }
    if count == 1 {
        return Ok(found.unwrap_or(UTC));
    }
    let mut out = [None; 3];
    let mut n = 0;
    for (i, z) in ZONES.iter().enumerate() {
        if n < out.len() && contains_name(z.name.as_bytes(), typed) {
            out[n] = Some(i as ZoneId);
            n += 1;
        }
    }
    Err(out)
}
